const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const brazil = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Brazil'));

  const date2007 = ['2007-01-01', '2007-12-31'];
  const date2019 = ['2019-01-01', '2019-12-31'];

  // 2. Data Acquisition - MODIS Active Fire Data
  const fires2007 = ee.ImageCollection('MODIS/006/MCD14ML')
    .filterBounds(brazil)
    .filterDate(date2007[0], date2007[1]);

  const fires2019 = ee.ImageCollection('MODIS/006/MCD14ML')
    .filterBounds(brazil)
    .filterDate(date2019[0], date2019[1]);

  // Check collection sizes
  const count2007 = fires2007.size().getInfo();
  const count2019 = fires2019.size().getInfo();

  console.log(`2007 Fire Images: ${count2007}`);
  console.log(`2019 Fire Images: ${count2019}`);

  if (count2007 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Count fire detections - use 'confidence' band to count fire pixels
  // Fire pixels have confidence > 0
  const countFires2007 = fires2007
    .map(function(image) {
      return image.select('confidence').gt(0);
    })
    .sum()
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: brazil,
      scale: 1000,
      maxPixels: 1e9
    }).get('confidence').getInfo();

  const countFires2019 = fires2019
    .map(function(image) {
      return image.select('confidence').gt(0);
    })
    .sum()
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: brazil,
      scale: 1000,
      maxPixels: 1e9
    }).get('confidence').getInfo();

  console.log(`2007 Fire Count: ${Math.round(countFires2007)}`);
  console.log(`2019 Fire Count: ${Math.round(countFires2019)}`);

  // 4. Validation & Final Answer
  if (countFires2007 === null || countFires2019 === null || 
      isNaN(countFires2007) || isNaN(countFires2019)) {
    console.log("<answer>C3</answer>");
  } else if (countFires2019 < countFires2007) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
